theorem sum {ι : Type*} {s : Finset ι} {G : ι → 𝕜 → E}
    (h : ∀ σ, Meromorphic (G σ)) :
    Meromorphic (∑ n ∈ s, G n) := fun x ↦ MeromorphicAt.sum (h · x)

theorem prod {ι : Type*} {s : Finset ι} {F : ι → 𝕜 → 𝕜}
    (h : ∀ σ, Meromorphic (F σ)) :
    Meromorphic (∏ n ∈ s, F n) := fun x ↦ MeromorphicAt.prod (h · x)
